task get_pell(n: int) returns (r: int)
  requires n >= 0
  ensures r == pell(n)
{
  if n == 0 {
    r := 0;
  } else {
    if n == 1 {
      r := 1;
    } else {
      var a: int := 0;
      var b: int := 1;
      var i: int := 2;
      while i <= n
        invariant 0 <= i and i <= n
        invariant a == pell(i - 2)
        invariant b == pell(i - 1)
        decreases n - i + 1
      {
        a := b;
        b := 2 * b + a;
        i := i + 1;
      }
      r := b;
    }
  }
}
